function SatinalmaSiparis(a){fetch("/AddOns/Partner/purchase/cfc/purchase_service.cfc?method=SAVEORDER_gpt&internal_id="+a,{method:"POST",headers:{"Content-Type":"application/json"}}).then(a=>a.json()).then(a=>{"success"===a.RES?(alert("İşlem başarılı!"),window.location.reload()):"error"===a.RES&&alert("Bir hata oluştu!")}).catch(a=>{console.error("Hata:",a),alert("Sunucuya bağlanırken bir hata oluştu!")})}